function downloadSection(lang){const bg=lang==='bg';return `<div class="download-intro"><img src="assets/tasktime.svg" alt="TaskTime" width="72" height="72"><p>${bg?'Избери браузъра, в който работиш, свали файла и следвай стъпките по-долу. Инсталирането отнема около минута.':'Choose the browser you work in, download the file and follow the steps below. Installation takes about a minute.'}</p></div><div class="cards browser-cards">${['Chrome','Opera'].map(browser=>`<article class="card"><div class="browser-title"><img src="assets/${browser.toLowerCase()}.svg" alt="" width="44" height="44"><div><h3>${browser==='Chrome'?'Google Chrome':'Opera Browser'}</h3><small>${bg?'ВЕРСИЯ':'VERSION'} 0.1.6</small></div></div><a class="download-button" download href="downloads/tasktime-${browser.toLowerCase()}-0.1.6.zip"><span aria-hidden="true">↓</span> ${bg?'Свали за':'Download for'} ${browser}<span class="file-size">~28 KB</span></a><a class="install-link" href="#installation">${bg?'Как се инсталира?':'How do I install it?'} →</a></article>`).join('')}</div><div id="installation" class="installation"><span class="eyebrow">${bg?'ИНСТАЛИРАНЕ':'INSTALLATION'}</span><h3>${bg?'В 6 стъпки':'In 6 steps'}</h3><div class="callout danger"><strong>${bg?'⚠ ВАЖНО: Пази папката на добавката!':'⚠ IMPORTANT: Keep the extension folder safe!'}</strong><p>${bg?'Браузърът зарежда TaskTime директно от папката, която си избрал. Сложи я на безопасно място, където няма да я изтриеш случайно (например <code>Documents\\TaskTime</code>), и не я пипай след това.':'The browser loads TaskTime directly from the folder you chose. Put it somewhere safe where you will not delete it by accident (for example <code>Documents\\TaskTime</code>) and leave it there.'}</p><ul><li>${bg?'<strong>Ако изтриеш папката</strong>, добавката спира да работи.':'<strong>If you delete the folder</strong>, the extension stops working.'}</li><li>${bg?'<strong>Ако преместиш папката</strong> или премахнеш добавката, трябва да я заредиш наново и <strong>всичките ти записи ще се загубят</strong>.':'<strong>If you move the folder</strong> or remove the extension, you have to load it again and <strong>all your records will be lost</strong>.'}</li><li>${bg?'<strong>Преди да местиш, триеш или преинсталираш:</strong> отвори отчета → Настройки → <strong>„Свали архив (JSON)“</strong>. След новата инсталация натисни <strong>„Възстанови от архив“</strong> и избери файла.':'<strong>Before moving, deleting or reinstalling:</strong> open the report → Settings → <strong>“Download backup (JSON)”</strong>. After reinstalling, press <strong>“Restore from backup”</strong> and choose the file.'}</li></ul></div><ol><li>${bg?'Свали файла за своя браузър и го разархивирай (десен бутон → Extract All) в постоянна папка, например <code>Documents\\TaskTime</code>.':'Download the file for your browser and extract it (right-click → Extract All) into a permanent folder, for example <code>Documents\\TaskTime</code>.'}</li><li>${bg?'Копирай този адрес в адресната лента и натисни Enter:':'Copy this address into the address bar and press Enter:'}<div class="browser-addresses"><code>chrome://extensions</code><code>opera://extensions</code></div></li><li>${bg?'Включи <strong>Developer mode</strong> (Режим за програмисти) — горе вдясно в Chrome, горе в Opera.':'Turn on <strong>Developer mode</strong> — top right in Chrome, at the top in Opera.'}</li><li>${bg?'Натисни <strong>Load unpacked</strong> (Зареждане на разопаковано) и избери разархивираната папка.':'Click <strong>Load unpacked</strong> and choose the extracted folder.'}</li><li>${bg?'Закачи иконката TaskTime (часовник с отметка) в лентата на браузъра, за да е винаги под ръка.':'Pin the TaskTime icon (clock with a checkmark) to the browser toolbar so it is always at hand.'}</li><li>${bg?'Презареди отворените страници на Redstone и Ximble. Готово.':'Reload any open Redstone and Ximble pages. Done.'}</li></ol><div class="update-steps"><h3>${bg?'Как се обновява':'How to update'}</h3><p>${bg?'Когато излезе нова версия, на иконката на TaskTime се появява <strong>↑</strong>, а в отчета — съобщение с бутон към този сайт.':'When a new version is out, <strong>↑</strong> appears on the TaskTime icon and the report shows a message with a link to this site.'}</p><ol><li>${bg?'Свали новия файл от този сайт.':'Download the new file from this site.'}</li><li>${bg?'Разархивирай го <strong>върху същата папка</strong>, в която е добавката, и избери <strong>Replace</strong> (замени файловете).':'Extract it <strong>over the same folder</strong> the extension is in and choose <strong>Replace</strong>.'}</li><li>${bg?'Отвори страницата с разширения: напиши <code>chrome://extensions</code> (Chrome) или <code>opera://extensions</code> (Opera) в адресната лента. Може и от отчета: Настройки → <strong>„Отвори разширенията“</strong>.':'Open the extensions page: type <code>chrome://extensions</code> (Chrome) or <code>opera://extensions</code> (Opera) in the address bar. Or from the report: Settings → <strong>“Open extensions”</strong>.'}</li><li>${bg?'Намери картата <strong>TaskTime</strong> и натисни кръглата стрелка <strong>↻</strong> (Reload / Презареди) — в Chrome е долу вдясно на картата, в Opera е до името.':'Find the <strong>TaskTime</strong> card and press the round arrow <strong>↻</strong> (Reload) — in Chrome it is at the bottom right of the card, in Opera next to the name.'}</li><li>${bg?'Готово. В отчета → Настройки → Версия трябва да пише новата версия. Записите ти остават.':'Done. Report → Settings → Version should show the new version. Your records stay.'}</li></ol><p class="caption">${bg?'Забравиш ли стъпка 4, отчетът ще ти напомни с лента „Довърши обновяването“. Не премахвай добавката и не я зареждай от нова папка.':'If you forget step 4, the report reminds you with a “Finish updating” bar. Do not remove the extension or load it from a new folder.'}</p></div></div><p class="caption">${bg?'Записите ти остават само в твоя браузър. Сайтът и добавката не изпращат данни никъде. Проектът не е свързан с Google, Opera, Second Spectrum или Ximble.':'Your records stay only in your browser. Neither this site nor the extension sends data anywhere. This project is not affiliated with Google, Opera, Second Spectrum or Ximble.'}</p>`}
for(const lang of ['bg','en']){const d=data[lang],bg=lang==='bg';d.badge=bg?'ДОБАВКА ЗА CHROME И OPERA':'EXTENSION FOR CHROME AND OPERA';d.aside=bg?'Версия 0.1.6':'Version 0.1.6';d.items.unshift(bg?'Сваляне и инсталиране':'Download & install');d.sections.unshift([bg?'Инсталирай TaskTime.':'Install TaskTime.',downloadSection(lang)]);}
const baseRender=render;render=function(lang){baseRender(lang);const a=document.createElement('a');a.href='#s0';a.className='hero-download';a.textContent=lang==='en'?'↓ Download TaskTime':'↓ Свали TaskTime';document.querySelector('.hero').append(a)};render(document.documentElement.lang);
